'use strict';

// MODULES //

var abs = require( '@stdlib/math/base/special/abs' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );


// MAIN //

/**
* Computes a norm of a triangular or trapezoidal matrix.
*
* ## Notes
*
* -   Adapted from LAPACK's DLANTR; see the accompanying NOTICE.
* -   Frobenius accumulation uses scaled sums of squares to avoid unnecessary overflow and underflow.
*
* @private
* @param {integer} norm - normalized norm
* @param {integer} uplo - triangle type
* @param {integer} diag - diagonal type
* @param {NonNegativeInteger} M - number of rows
* @param {NonNegativeInteger} N - number of columns
* @param {Float64Array} A - input matrix
* @param {integer} sa1 - row stride
* @param {integer} sa2 - column stride
* @param {NonNegativeInteger} oa - matrix offset
* @param {Float64Array} work - scratch array
* @param {integer} sw - workspace stride
* @param {NonNegativeInteger} ow - workspace offset
* @returns {number} norm
*/
function dlantr( norm, uplo, diag, M, N, A, sa1, sa2, oa, work, sw, ow ) { // eslint-disable-line max-params
	var sumsq;
	var scale;
	var value;
	var start;
	var stop;
	var unit;
	var sum;
	var ax;
	var r;
	var i;
	var j;

	if ( M === 0 || N === 0 ) {
		return 0.0;
	}
	unit = ( diag === 132 );
	value = 0.0;
	scale = 0.0;
	sumsq = 1.0;
	if ( norm === 73 ) {
		for ( i = 0; i < M; i++ ) {
			work[ ow+(i*sw) ] = 0.0;
		}
	}
	for ( j = 0; j < N; j++ ) {
		if ( uplo === 121 ) {
			start = 0;
			stop = ( j < M ) ? j : M-1;
		} else {
			start = j;
			stop = M-1;
		}
		sum = 0.0;
		for ( i = start; i <= stop; i++ ) {
			ax = ( unit && i === j ) ? 1.0 : abs( A[ oa+(i*sa1)+(j*sa2) ] );
			if ( norm === 77 ) {
				if ( ax > value || isnan( ax ) ) {
					value = ax;
				}
			} else if ( norm === 49 ) {
				sum += ax;
			} else if ( norm === 73 ) {
				work[ ow+(i*sw) ] += ax;
			} else {
				if ( isnan( ax ) ) {
					return NaN;
				}
				if ( ax === PINF ) {
					scale = PINF;
				} else if ( ax !== 0.0 && scale !== PINF ) {
					if ( scale < ax ) {
						r = scale / ax;
						sumsq = 1.0 + ( sumsq*r*r );
						scale = ax;
					} else {
						r = ax / scale;
						sumsq += r*r;
					}
				}
			}
		}
		if ( norm === 49 && ( sum > value || isnan( sum ) ) ) {
			value = sum;
		}
	}
	if ( norm === 73 ) {
		for ( i = 0; i < M; i++ ) {
			sum = work[ ow+(i*sw) ];
			if ( sum > value || isnan( sum ) ) {
				value = sum;
			}
		}
	} else if ( norm === 70 ) {
		value = scale * sqrt( sumsq );
	}
	return value;
}


// EXPORTS //

module.exports = dlantr;
